window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f935b66f7aa3442c"]={"versions": [{"id": "FIG-f935b66f7aa3442c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Configuration-Metamodells (ECUC) für das BSW-Modul <code>EcuM</code> (ECU State Manager Fixed). Das Diagramm spezifiziert die hierarchische Container-Struktur auf Parameterebene gemäß AUTOSAR-Konfigurationsstandard.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Wurzel-Entität ist die Moduldefinition <code>EcuM : EcucModuleDef</code> mit den Multiplizitätsgrenzen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen (<code>+container</code>) sind drei Hauptcontainer des Typs <code>EcucParamConfContainerDef</code> untergeordnet:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMGeneral</code>: Allgemeine Modulparameter ohne explizit deklarierte Multiplizitätsattribute im Containerkasten.</li>\n<li><code>EcuMFixedGeneral</code>: Spezifische allgemeine Einstellungen für den EcuM Fixed mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMConfiguration</code>: Hauptkonfigurationscontainer mit <code>upperMultiplicity = 1</code>, <code>lowerMultiplicity = 1</code> und dem Attribut <code>multipleConfigurationContainer = true</code>.</li>\n</ul>\n<p class=\"fig-p\"><code>EcuMConfiguration</code> aggregiert über Kompositionsbeziehungen (<code>+subContainer</code>) zwei Subcontainer des Typs <code>EcucParamConfContainerDef</code>:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMCommonConfiguration</code>: Gemeinsame Konfigurationsparameter mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMFixedConfiguration</code>: Fixed-spezifische Konfigurationsparameter mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodell-Struktur der Konfigurationsdefinition dar. Es modelliert kein dynamisches Laufzeitverhalten und keine Sequenzabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Konfigurationsgeneratoren und XML-Beschreibungsdateien (ARXML):</p>\n<ul class=\"fig-list\">\n<li>Eine EcuM-Modulkonfiguration darf höchstens einmal instanziiert werden (<code>0..1</code>).</li>\n<li><code>EcuMConfiguration</code> ist als Pflichtcontainer (<code>1..1</code>) vorgegeben und als <code>multipleConfigurationContainer = true</code> gekennzeichnet, womit er die Wurzel für Post-Build- bzw. wählbare Konfigurationssätze bildet.</li>\n<li><code>EcuMCommonConfiguration</code> ist innerhalb der Konfiguration verpflichtend vorzusehen (<code>1..1</code>), während <code>EcuMFixedGeneral</code> und <code>EcuMFixedConfiguration</code> optionale Container darstellen (<code>0..1</code>).</li>\n</ul>"}, {"id": "FIG-a80805a609822628", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Configuration-Metamodells (ECUC) für das BSW-Modul <code>EcuM</code> (ECU State Manager Fixed). Das Diagramm spezifiziert die hierarchische Container-Struktur auf Parameterebene gemäß AUTOSAR-Konfigurationsstandard.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Wurzel-Entität ist die Moduldefinition <code>EcuM : EcucModuleDef</code> mit den Multiplizitätsgrenzen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen (<code>+container</code>) sind drei Hauptcontainer des Typs <code>EcucParamConfContainerDef</code> untergeordnet:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMGeneral</code>: Allgemeine Modulparameter ohne explizit deklarierte Multiplizitätsattribute im Containerkasten.</li>\n<li><code>EcuMFixedGeneral</code>: Spezifische allgemeine Einstellungen für den EcuM Fixed mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMConfiguration</code>: Hauptkonfigurationscontainer mit <code>upperMultiplicity = 1</code>, <code>lowerMultiplicity = 1</code> und dem Attribut <code>multipleConfigurationContainer = true</code>.</li>\n</ul>\n<p class=\"fig-p\"><code>EcuMConfiguration</code> aggregiert über Kompositionsbeziehungen (<code>+subContainer</code>) zwei Subcontainer des Typs <code>EcucParamConfContainerDef</code>:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMCommonConfiguration</code>: Gemeinsame Konfigurationsparameter mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMFixedConfiguration</code>: Fixed-spezifische Konfigurationsparameter mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodell-Struktur der Konfigurationsdefinition dar. Es modelliert kein dynamisches Laufzeitverhalten und keine Sequenzabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Konfigurationsgeneratoren und XML-Beschreibungsdateien (ARXML):</p>\n<ul class=\"fig-list\">\n<li>Eine EcuM-Modulkonfiguration darf höchstens einmal instanziiert werden (<code>0..1</code>).</li>\n<li><code>EcuMConfiguration</code> ist als Pflichtcontainer (<code>1..1</code>) vorgegeben und als <code>multipleConfigurationContainer = true</code> gekennzeichnet, womit er die Wurzel für Post-Build- bzw. wählbare Konfigurationssätze bildet.</li>\n<li><code>EcuMCommonConfiguration</code> ist innerhalb der Konfiguration verpflichtend vorzusehen (<code>1..1</code>), während <code>EcuMFixedGeneral</code> und <code>EcuMFixedConfiguration</code> optionale Container darstellen (<code>0..1</code>).</li>\n</ul>"}, {"id": "FIG-4a1c4ebd5b8c6370", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Configuration-Metamodells (ECUC) für das BSW-Modul <code>EcuM</code> (ECU State Manager Fixed). Das Diagramm spezifiziert die hierarchische Container-Struktur auf Parameterebene gemäß AUTOSAR-Konfigurationsstandard.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Wurzel-Entität ist die Moduldefinition <code>EcuM : EcucModuleDef</code> mit den Multiplizitätsgrenzen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen (<code>+container</code>) sind drei Hauptcontainer des Typs <code>EcucParamConfContainerDef</code> untergeordnet:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMGeneral</code>: Allgemeine Modulparameter ohne explizit deklarierte Multiplizitätsattribute im Containerkasten.</li>\n<li><code>EcuMFixedGeneral</code>: Spezifische allgemeine Einstellungen für den EcuM Fixed mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMConfiguration</code>: Hauptkonfigurationscontainer mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<p class=\"fig-p\"><code>EcuMConfiguration</code> aggregiert über Kompositionsbeziehungen (<code>+subContainer</code>) zwei Subcontainer des Typs <code>EcucParamConfContainerDef</code>:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMCommonConfiguration</code>: Gemeinsame Konfigurationsparameter mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMFixedConfiguration</code>: Fixed-spezifische Konfigurationsparameter mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodell-Struktur der Konfigurationsdefinition dar. Es modelliert kein dynamisches Laufzeitverhalten und keine Sequenzabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Konfigurationsgeneratoren und XML-Beschreibungsdateien (ARXML):</p>\n<ul class=\"fig-list\">\n<li>Eine EcuM-Modulkonfiguration darf höchstens einmal instanziiert werden (<code>0..1</code>).</li>\n<li><code>EcuMConfiguration</code> ist als Pflichtcontainer (<code>1..1</code>) ohne Kennzeichnung als multipler Konfigurationscontainer definiert.</li>\n<li><code>EcuMCommonConfiguration</code> ist innerhalb der Konfiguration verpflichtend vorzusehen (<code>1..1</code>), während <code>EcuMFixedGeneral</code> und <code>EcuMFixedConfiguration</code> optionale Container darstellen (<code>0..1</code>).</li>\n</ul>"}, {"id": "FIG-a16a7b0640844b7e", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Configuration-Metamodells (ECUC) für das BSW-Modul <code>EcuM</code> (ECU State Manager Fixed). Das Diagramm spezifiziert die hierarchische Container-Struktur auf Parameterebene gemäß AUTOSAR-Konfigurationsstandard.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Wurzel-Entität ist die Moduldefinition <code>EcuM : EcucModuleDef</code> mit den Multiplizitätsgrenzen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen (<code>+container</code>) sind drei Hauptcontainer des Typs <code>EcucParamConfContainerDef</code> untergeordnet:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMGeneral</code>: Allgemeine Modulparameter ohne explizit deklarierte Multiplizitätsattribute im Containerkasten.</li>\n<li><code>EcuMFixedGeneral</code>: Spezifische allgemeine Einstellungen für den EcuM Fixed mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMConfiguration</code>: Hauptkonfigurationscontainer mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<p class=\"fig-p\"><code>EcuMConfiguration</code> aggregiert über Kompositionsbeziehungen (<code>+subContainer</code>) zwei Subcontainer des Typs <code>EcucParamConfContainerDef</code>:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMCommonConfiguration</code>: Gemeinsame Konfigurationsparameter mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>EcuMFixedConfiguration</code>: Fixed-spezifische Konfigurationsparameter mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodell-Struktur der Konfigurationsdefinition dar. Es modelliert kein dynamisches Laufzeitverhalten und keine Sequenzabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Konfigurationsgeneratoren und XML-Beschreibungsdateien (ARXML):</p>\n<ul class=\"fig-list\">\n<li>Eine EcuM-Modulkonfiguration darf höchstens einmal instanziiert werden (<code>0..1</code>).</li>\n<li><code>EcuMConfiguration</code> ist als Pflichtcontainer (<code>1..1</code>) ohne Kennzeichnung als multipler Konfigurationscontainer definiert.</li>\n<li><code>EcuMCommonConfiguration</code> ist innerhalb der Konfiguration verpflichtend vorzusehen (<code>1..1</code>), während <code>EcuMFixedGeneral</code> und <code>EcuMFixedConfiguration</code> optionale Container darstellen (<code>0..1</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-f935b66f7aa3442c", "to": "FIG-a80805a609822628", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a80805a609822628", "to": "FIG-4a1c4ebd5b8c6370", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Im Container <code>EcuMConfiguration</code> (<code>EcucParamConfContainerDef</code>) wurde das Attribut <code>multipleConfigurationContainer = true</code> entfernt.</li>\n</ul>"}, {"from": "FIG-4a1c4ebd5b8c6370", "to": "FIG-a16a7b0640844b7e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
